const input = $json;

// n8n usa como propiedad el Label del formulario.
// Admitimos tanto "Acción" como "accion" por seguridad.
const action = String(
  input['Acción'] ??
  input.accion ??
  ''
)
  .trim()
  .toUpperCase();

const evento_id = input.evento_id
  ? String(input.evento_id).trim()
  : null;

const nombre = input.nombre
  ? String(input.nombre).trim()
  : null;

let categoria = input.categoria
  ? String(input.categoria).trim().toUpperCase()
  : null;

// Normalizar, por ejemplo:
// "CIENCIA FICCION" → "CIENCIA_FICCION"
if (categoria) {
  categoria = categoria
    .replace(/\s+/g, '_')
    .replace(/-+/g, '_');
}

const descripcion = input.descripcion
  ? String(input.descripcion).trim()
  : null;

const fecha = input.fecha
  ? String(input.fecha).trim()
  : null;

const hora = input.hora
  ? String(input.hora).trim()
  : null;

const lugar = input.lugar
  ? String(input.lugar).trim()
  : null;

const capacidad =
  input.capacidad !== undefined &&
  input.capacidad !== null &&
  input.capacidad !== ''
    ? Number(input.capacidad)
    : null;

const imagen_url = input.imagen_url
  ? String(input.imagen_url).trim()
  : null;

const organizador = input.organizador
  ? String(input.organizador).trim()
  : null;

const estado = input.estado
  ? String(input.estado).trim().toUpperCase()
  : null;

const accionesPermitidas = [
  'CREATE',
  'READ',
  'UPDATE',
  'CANCEL',
  'CLOSE',
];

const categoriasPermitidas = [
  'COMICS',
  'COSPLAY',
  'ANIME',
  'GAMING',
  'CIENCIA_FICCION',
  'TALLERES',
];

const estadosPermitidos = [
  'BORRADOR',
  'PUBLICADO',
  'CERRADO',
  'CANCELADO',
];

let error = null;

// Acción
if (!accionesPermitidas.includes(action)) {
  error = 'Acción no válida';
}

// CREATE
if (!error && action === 'CREATE') {
  if (!nombre) {
    error = 'El nombre es obligatorio';
  } else if (!categoria) {
    error = 'La categoría es obligatoria';
  } else if (!categoriasPermitidas.includes(categoria)) {
    error = 'Categoría no válida';
  } else if (!descripcion) {
    error = 'La descripción es obligatoria';
  } else if (!fecha) {
    error = 'La fecha es obligatoria';
  } else if (!hora) {
    error = 'La hora es obligatoria';
  } else if (!lugar) {
    error = 'El lugar es obligatorio';
  } else if (!Number.isInteger(capacidad) || capacidad <= 0) {
    error = 'La capacidad debe ser un entero mayor que 0';
  } else if (!organizador) {
    error = 'El organizador es obligatorio';
  } else if (estado && !estadosPermitidos.includes(estado)) {
    error = 'Estado no válido';
  }
}

// Acciones que requieren evento_id
if (
  !error &&
  ['READ', 'UPDATE', 'CANCEL', 'CLOSE'].includes(action)
) {
  if (!evento_id) {
    error = 'evento_id es obligatorio';
  }
}

// UPDATE
if (!error && action === 'UPDATE') {
  const hayCambios =
    nombre !== null ||
    categoria !== null ||
    descripcion !== null ||
    fecha !== null ||
    hora !== null ||
    lugar !== null ||
    capacidad !== null ||
    imagen_url !== null ||
    organizador !== null ||
    estado !== null;

  if (!hayCambios) {
    error = 'Debe enviarse al menos un dato para actualizar';
  }

  if (
    !error &&
    categoria &&
    !categoriasPermitidas.includes(categoria)
  ) {
    error = 'Categoría no válida';
  }

  if (
    !error &&
    estado &&
    !estadosPermitidos.includes(estado)
  ) {
    error = 'Estado no válido';
  }
}

return [
  {
    json: {
      route: error ? 'INVALID' : action,
      action,
      evento_id,
      nombre,
      categoria,
      descripcion,
      fecha,
      hora,
      lugar,
      capacidad,
      imagen_url,
      organizador,
      estado,
      error,
    },
  },
];

