const crypto = require('crypto');

const entrada = $json;
const ahora = new Date().toISOString();

return [{
  json: {
    evento_id: `evt_${crypto.randomUUID()}`,
    nombre: entrada.nombre,
    categoria: entrada.categoria,
    descripcion: entrada.descripcion,
    fecha: entrada.fecha,
    hora: entrada.hora,
    lugar: entrada.lugar,
    capacidad: entrada.capacidad,
    imagen_url: entrada.imagen_url ?? '',
    organizador: entrada.organizador,
    estado: entrada.estado || 'BORRADOR',
    fecha_creacion: ahora,
    fecha_actualizacion: ahora
  }
}];

const crypto = require('crypto');

const evento = $('Generar evento').first().json;

return [{
  json: {
    auditoria_id: `aud_evt_${crypto.randomUUID()}`,
    evento_id: evento.evento_id,
    accion: 'CREATE',
    fecha: new Date().toISOString(),
    resultado: 'OK',
    detalle: `Evento "${evento.nombre}" creado con estado ${evento.estado}`
  }
}];

const crypto = require('crypto');

const evento = $('Buscar evento por ID').first().json;

return [{
  json: {
    auditoria_id: `aud_evt_${crypto.randomUUID()}`,
    evento_id: evento.evento_id,
    accion: 'READ',
    fecha: new Date().toISOString(),
    resultado: 'OK',
    detalle: `Consulta del evento "${evento.nombre}"`
  }
}];

const evento = $('Buscar evento por ID').first().json;

return [{
  json: {
    ok: true,
    message: 'Evento encontrado',
    evento: {
      evento_id: evento.evento_id,
      nombre: evento.nombre,
      categoria: evento.categoria,
      descripcion: evento.descripcion,
      fecha: evento.fecha,
      hora: evento.hora,
      lugar: evento.lugar,
      capacidad: evento.capacidad,
      imagen_url: evento.imagen_url,
      organizador: evento.organizador,
      estado: evento.estado,
      fecha_creacion: evento.fecha_creacion,
      fecha_actualizacion: evento.fecha_actualizacion
    }
  }
}];

const entrada = $('Normalizar y validar evento').first().json;

return [{
  json: {
    ok: false,
    error: 'Evento no encontrado',
    evento_id: entrada.evento_id
  }
}];

const entrada = $('Normalizar y validar evento').first().json;

return [{
  json: {
    ok: false,
    error: 'Evento no encontrado',
    evento_id: entrada.evento_id
  }
}];

const crypto = require('crypto');

const evento = $('Preparar actualización evento').first().json;

return [{
  json: {
    auditoria_id: `aud_evt_${crypto.randomUUID()}`,
    evento_id: evento.evento_id,
    accion: 'UPDATE',
    fecha: new Date().toISOString(),
    resultado: 'OK',
    detalle: `Evento "${evento.nombre}" actualizado correctamente`
  }
}];

const evento = $('Preparar actualización evento').first().json;

return [{
  json: {
    ok: true,
    message: 'Evento actualizado correctamente',
    evento
  }
}];

const entrada = $('Normalizar y validar evento').first().json;

return [{
  json: {
    ok: false,
    error: 'Evento no encontrado',
    evento_id: entrada.evento_id
  }
}];

const evento = $('Buscar evento para cambiar estado').first().json;
const entrada = $('Normalizar y validar evento').first().json;

const nuevoEstado =
  entrada.action === 'CANCEL'
    ? 'CANCELADO'
    : 'CERRADO';

return [{
  json: {
    evento_id: evento.evento_id,
    nombre: evento.nombre,
    categoria: evento.categoria,
    descripcion: evento.descripcion,
    fecha: evento.fecha,
    hora: evento.hora,
    lugar: evento.lugar,
    capacidad: evento.capacidad,
    imagen_url: evento.imagen_url,
    organizador: evento.organizador,
    estado_anterior: evento.estado,
    estado: nuevoEstado,
    accion: entrada.action,
    fecha_creacion: evento.fecha_creacion,
    fecha_actualizacion: new Date().toISOString()
  }
}];

const crypto = require('crypto');

const evento = $('Preparar cambio de estado').first().json;

return [{
  json: {
    auditoria_id: `aud_evt_${crypto.randomUUID()}`,
    evento_id: evento.evento_id,
    accion: evento.accion,
    fecha: new Date().toISOString(),
    resultado: 'OK',
    detalle: `Evento "${evento.nombre}" cambió de ${evento.estado_anterior} a ${evento.estado}`
  }
}];

const evento = $('Preparar cambio de estado').first().json;

return [{
  json: {
    ok: true,
    message:
      evento.estado === 'CANCELADO'
        ? 'Evento cancelado correctamente'
        : 'Evento cerrado correctamente',
    evento: {
      evento_id: evento.evento_id,
      nombre: evento.nombre,
      estado_anterior: evento.estado_anterior,
      estado: evento.estado,
      fecha_actualizacion: evento.fecha_actualizacion
    }
  }
}];

const entrada = $('Normalizar y validar evento').first().json;

return [{
  json: {
    ok: false,
    error: entrada.error || 'Solicitud inválida',
    action: entrada.action || null,
    evento_id: entrada.evento_id || null
  }
}];
